
import {load, save, replace, reset, ensureDay, ensureWeek, installSyncListeners} from "./store.js";
import {add, avg, cap, clamp, escape, fmtDate, fmtHours, fmtMin, fmtMonth, fmtShortDate, key, monthGrid, MOODS, LEGACY_MOODS, moodScore, parse, pct, startWeek, timeEnd, week, weekKey, weekLabel, weekNumber, DAY_KEYS, DAY_NUMS, minutesFromTime} from "./utils.js";
import {registerServiceWorker} from "./notifications.js";

const app=document.querySelector("#app");
const CONFIG=window.PLAN20_CONFIG||{vapidPublicKey:""};
let data=load();
let state={
  page:"plan",view:"planning",
  date:key(new Date()),month:key(new Date(new Date().getFullYear(),new Date().getMonth(),1)),
  mobileMenu:false,modal:null,deferredInstallPrompt:null,
  open:{what:true,agenda:true,nonneg:false,priorities:false,todos:true,habits:false,training:true,study:true,sleep:false,water:false,min:false,balance:true}
};
const NOTIFY_LOG_KEY="plan20-notify-log-v2";
let notifyLog={};
try{notifyLog=JSON.parse(localStorage.getItem(NOTIFY_LOG_KEY)||"{}")}catch{}
let reminderTimer=null;

const id=prefix=>`${prefix}-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;
const todayKey=()=>key(new Date());
const currentDate=()=>parse(state.date);
const currentWeekStart=()=>key(startWeek(currentDate()));
const dayRecord=(d=state.date)=>ensureDay(data,d);
const tasksFor=d=>data.tasks.filter(t=>t.date===(typeof d==="string"?d:key(d)));
const weekTasks=d=>week(d).flatMap(tasksFor);
const prioritiesFor=d=>{ const wk=weekKey(typeof d==="string"?parse(d):d); return data.priorities.filter(p=>p.weekStart===wk); };
const weekRecord = (d=currentDate()) => ensureWeek(data, weekKey(d));
const plannedDaysFor = d => weekRecord(d).plannedDays || {};
const dayHasPlan = d => { const k=typeof d==="string"?d:key(d); return !!plannedDaysFor(k)[k] || tasksFor(k).length>0 || data.training.some(t=>t.date===k); };
function setPlannedDay(date,value){ const k=key(parse(date)); setData(d=>{ const w=ensureWeek(d,weekKey(k)); w.plannedDays[k]=!!value; return d; }); }
function setWeeklyField(path,value){ setData(d=>{ const w=ensureWeek(d,currentWeekStart()); const p=String(path).split("."); if(p[0]==="balance")w.balance[p[1]]=value; else if(p[0]==="reflection")w.reflection[p[1]]=value; return d; }); }
function weekGeneralMood(w){ const vals=w.map(d=>data.days[key(d)]?.mood).filter(Boolean); if(!vals.length)return {label:"—",avg:0,count:0}; const score=avg(vals.map(moodScore)); const label=score>=4.5?"Excelente":score>=3.5?"Bien":score>=2.5?"Normal":score>=1.5?"Enojado":"Agotado"; return {label,avg:score,count:vals.length}; }
function repairPriorityRelations(){ const map=new Map(data.tasks.map(t=>[t.id,t])); data.priorities=data.priorities.map(p=>{ const ids=new Set((p.taskIds||[]).filter(id=>map.has(id))); for(const t of data.tasks)if(t.priorityId===p.id)ids.add(t.id); return {...p,taskIds:[...ids]}; }); for(const p of data.priorities)for(const id of p.taskIds||[]){const t=map.get(id);if(t&&!t.priorityId)t.priorityId=p.id;} }
repairPriorityRelations();
const isScheduled=(obj,d,field)=>{
  const vals=obj[field];
  return Array.isArray(vals)&&vals.length?vals.includes(parse(d).getDay()):true;
};
const habitScheduled=(h,d)=>{
  const vals=h.daysOfWeek;
  return Array.isArray(vals)&&vals.length?vals.includes(d.getDay()):true;
};
const activeNonneg=d=>data.nonNegotiables.filter(n=>n.active!==false&&isScheduled(n,d,"days"));
function nonnegDone(n,d=state.date){
  if(!isScheduled(n,d,"days"))return false;
  const r=data.days[d]||ensureDay(data,d);
  if(n.mode==="water")return Number(r.waterLiters)>=Number(data.settings.waterGoal);
  if(n.mode==="study")return Number(r.studyMinutes)>=Number(data.settings.studyGoalMinutes);
  if(n.mode==="sleep")return Number(r.sleepMinutes)>=Number(data.settings.sleepGoalMinutes)-30;
  if(n.mode==="training"){const slot=Number(n.slot)||0;return data.training.some(t=>t.date===d&&t.completed&&(slot?Number(t.slot)===slot:true));}
  return !!n.checks?.[d];
}
const habitDone=(h,d)=>!!h.logs?.[d];
const dayTaskPct=d=>pct(tasksFor(d).filter(t=>t.completed).length,tasksFor(d).length);
const dayHabitPct=d=>{
  const date=parse(d),hs=data.habits.filter(h=>habitScheduled(h,date));
  return pct(hs.filter(h=>habitDone(h,d)).length,hs.length);
};
const dayNonnegPct=d=>{
  const ns=activeNonneg(d);
  return pct(ns.filter(n=>nonnegDone(n,d)).length,ns.length);
};
function dayCompletion(d=state.date){
  const k=typeof d==="string"?d:key(d),tasks=tasksFor(k),ns=activeNonneg(k),hs=data.habits.filter(h=>habitScheduled(h,parse(k))),r=data.days[k],parts=[];
  if(tasks.length)parts.push([dayTaskPct(k),45]); if(ns.length)parts.push([dayNonnegPct(k),20]); if(hs.length)parts.push([dayHabitPct(k),15]);
  const plannedTraining=data.training.filter(t=>t.date===k); if(plannedTraining.length)parts.push([pct(plannedTraining.filter(t=>t.completed).length,plannedTraining.length),10]);
  if(r&&Number(r.studyMinutes)>0)parts.push([pct(r.studyMinutes,data.settings.studyGoalMinutes),5]); if(r&&Number(r.sleepMinutes)>0)parts.push([pct(r.sleepMinutes,data.settings.sleepGoalMinutes),5]);
  if(!parts.length)return 0; const weight=parts.reduce((s,x)=>s+x[1],0); return Math.round(parts.reduce((s,x)=>s+x[0]*x[1],0)/weight);
}
function weekCompletion(d=currentDate()){const planned=week(d).filter(x=>dayHasPlan(key(x)));return planned.length?Math.round(avg(planned.map(x=>dayCompletion(key(x))))):0;}
function weekPlannedCount(d=currentDate()){return week(d).filter(x=>dayHasPlan(key(x))).length;}
function weekPlannedTaskCount(d=currentDate()){return weekTasks(d).length;}
function habitWeekPct(w){
  let total=0,done=0;
  for(const h of data.habits)for(const d of w)if(habitScheduled(h,d)){total++;if(habitDone(h,key(d)))done++;}
  return pct(done,total);
}
function priorityProgress(p){
  const tids=p.taskIds||[];
  const ts=data.tasks.filter(t=>tids.includes(t.id));
  return ts.length?pct(ts.filter(t=>t.completed).length,ts.length):clamp(p.progress||0);
}
function goalProgress(g){
  const parts=[];
  const ts=data.tasks.filter(t=>(g.taskIds||[]).includes(t.id));
  const ps=data.priorities.filter(p=>(g.priorityIds||[]).includes(p.id));
  const hs=data.habits.filter(h=>(g.habitIds||[]).includes(h.id));
  if(ts.length)parts.push(pct(ts.filter(t=>t.completed).length,ts.length));
  if(ps.length)parts.push(avg(ps.map(priorityProgress)));
  if(hs.length)parts.push(avg(hs.map(h=>habitWeekPctFor(h,week(currentDate())))));
  return parts.length?Math.round(avg(parts)):clamp(g.progress||0);
}
const habitWeekPctFor=(h,w)=>{
  const s=w.filter(d=>habitScheduled(h,d));
  return pct(s.filter(d=>habitDone(h,key(d))).length,s.length);
};
function trainingWeekCount(w){return data.training.filter(t=>t.completed&&w.some(d=>key(d)===t.date)).length}
function setData(mutator){data=save(typeof mutator==="function"?mutator(data):mutator);render();scheduleLocalReminderCheck()}
function setDay(changes){setData(d=>{Object.assign(ensureDay(d,state.date),changes);return d})}
function setReflection(field,value){setData(d=>{ensureDay(d,state.date).reflection[field]=value;return d})}
function toast(msg){document.querySelector(".toast")?.remove();const e=document.createElement("div");e.className="toast";e.textContent=msg;document.body.appendChild(e);setTimeout(()=>e.remove(),2400)}
function icon(name){
  const p={
    calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M8 2v6M16 2v6M3 10h18"/>',
    target:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="m14.5 9.5 4-4M18.5 5.5h-3M18.5 5.5v3"/>',
    chart:'<path d="M4 19V9M10 19V5M16 19v-8M2 19h20"/>',
    spark:'<path d="m12 2 1.7 6.3L20 10l-6.3 1.7L12 18l-1.7-6.3L4 10l6.3-1.7L12 2Z"/>',
    settings:'<circle cx="12" cy="12" r="3"/><path d="M19 15.2a7.5 7.5 0 0 0 .1-6.4l2-1.1-2-3.1-2.1 1a7.7 7.7 0 0 0-5.5-3.2L11.2 0H7.6L7.2 2.4a7.7 7.7 0 0 0-5.5 3.2l-2.1-1-2 3.1 2 1.1a7.5 7.5 0 0 0 .1 6.4l-2 1.1 2 3.1 2.1-1a7.7 7.7 0 0 0 5.5-3.2l.4 2.4h3.6l.4-2.4a7.7 7.7 0 0 0 5.5-3.2l2.1 1 2-3.1z"/>',
    bell:'<path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9ZM10 21h4"/>',
    back:'<path d="m15 18-6-6 6-6"/>',
    next:'<path d="m9 18 6-6-6-6"/>'
  };
  return `<svg viewBox="0 0 24 24" aria-hidden="true">${p[name]||p.spark}</svg>`;
}
function bar(v,tone="blue"){return `<div class="bar bar-${tone}"><span style="width:${clamp(v)}%"></span></div>`}
function section(id,title,ic,summary,body,action=""){
  const open=state.open[id]!==false;
  return `<section class="card section-card ${open?"is-open":"is-closed"}"><button class="section-head" data-action="toggle" data-id="${id}"><span class="section-title"><span class="section-icon">${ic}</span>${escape(title)}</span><span class="section-right">${summary?`<span class="section-summary">${summary}</span>`:""}<span class="chevron">${open?"−":"⌄"}</span></span></button>${action?`<div class="section-action">${action}</div>`:""}${open?`<div class="section-body">${body}</div>`:""}</section>`;
}
const empty=(msg,action="")=>`<div class="empty-state"><span>${escape(msg)}</span>${action}</div>`;
function render(){
  document.body.classList.toggle("nav-open",state.mobileMenu);
  app.innerHTML=appShell();
  bindGlobal();
}
function appShell(){
  const tabs=state.page==="plan"?"<div class=\"segmented\"><button class=\""+(state.view==="planning"?"active":"")+"\" data-action=\"view\" data-view=\"planning\">Planificación</button><button class=\""+(state.view==="day"?"active":"")+"\" data-action=\"view\" data-view=\"day\">Día</button><button class=\""+(state.view==="week"?"active":"")+"\" data-action=\"view\" data-view=\"week\">Semana</button><button class=\""+(state.view==="month"?"active":"")+"\" data-action=\"view\" data-view=\"month\">Mes</button></div>":"";
  return `<div class="app-shell"><aside class="sidebar ${state.mobileMenu?"mobile-open":""}"><div class="brand"><span class="brand-leaf">◢</span><div><strong>PLAN 2.0</strong><small>Pequeños hábitos,<br>grandes resultados.</small></div></div><nav class="main-nav">${[["plan","Plan","calendar"],["goals","Metas","target"],["progress","Progreso","chart"],["insights","Insights","spark"],["settings","Configuración","settings"]].map(([p,l,i])=>`<button class="nav-item ${state.page===p?"active":""}" data-action="nav" data-page="${p}">${icon(i)}<span>${l}</span></button>`).join("")}</nav><div class="sidebar-bottom"><button class="sidebar-notify" data-action="notification-settings">${icon("bell")}<span>Notificaciones</span><em>${data.notifications.enabled?"ON":"OFF"}</em></button><div class="sidebar-quote">Cree en ti</div></div></aside>${state.mobileMenu?`<div class="mobile-scrim" data-action="mobile-menu"></div>`:""}<main class="main-shell"><header class="topbar"><button class="mobile-menu" data-action="mobile-menu" aria-label="Abrir menú">☰</button><div class="top-date"><button data-action="date-nav" data-delta="-1" aria-label="Anterior">${icon("back")}</button><div><strong>${cap(fmtMonth(currentDate()))}</strong><small>Semana ${weekNumber(currentDate())} · ${weekLabel(currentDate())}</small></div><button data-action="date-nav" data-delta="1" aria-label="Siguiente">${icon("next")}</button></div>${tabs}<div class="top-actions"><button class="today-btn" data-action="today">Hoy</button><button class="icon-btn" data-action="notification-test" title="Probar notificación">${icon("bell")}</button></div></header><div class="content-wrap">${renderPage()}</div></main>${state.modal?renderModal():""}</div>`;
}
function renderPage(){
  if(state.page==="goals")return renderGoals();
  if(state.page==="progress")return renderProgress();
  if(state.page==="insights")return renderInsights();
  if(state.page==="settings")return renderSettings();
  if(state.view==="planning")return renderPlanning();if(state.view==="week")return renderWeek();
  if(state.view==="month")return renderMonth();
  return renderDay();
}
function moodButtonsFor(r){const list=r.mood==="Bajo"?MOODS.concat(LEGACY_MOODS):MOODS;return list.map(m=>"<button class='planner-mood "+(r.mood===m[0]?"selected":"")+"' data-action='mood-date' data-date='"+state.date+"' data-mood='"+escape(m[0])+"'><span>"+m[1]+"</span></button>").join("");}
function renderPlanning(){const d=currentDate(),w=week(d),wr=ensureWeek(data,currentWeekStart());return "<div class='view-stack planning-page'><div class='page-heading'><div><span class='eyebrow'>PLANIFICACIÓN SEMANAL</span><h1>PLANIFICACIÓN SEMANAL</h1><p>Planifica primero. Después ejecuta lo que preparaste para esta semana.</p></div><button class='primary-btn' data-action='modal' data-type='priority-new'>＋ Prioridad</button></div><div class='planning-week-meta'><span>Semana "+escape(weekLabel(d))+"</span><b>"+weekPlannedCount(d)+" / 7 días planificados</b></div><div class='planner-scroll'><div class='planner-week-grid'>"+w.map(renderPlannerDay).join("")+"</div></div><div class='planning-columns'><div class='planning-col'><section class='card planner-block'><div class='planner-block-head'><div><h2>NO NEGOCIABLES</h2><p>Lo que se mantiene durante la semana.</p></div><button class='outline-btn small' data-action='modal' data-type='nonneg-new'>＋ Añadir</button></div>"+renderWeeklyNonneg(w)+"</section><section class='card planner-block'><div class='planner-block-head'><div><h2>HÁBITOS ADICIONALES</h2><p>Pequeñas acciones, grandes cambios.</p></div><button class='outline-btn small' data-action='modal' data-type='habit-new'>＋ Añadir</button></div>"+renderHabits(w)+"</section><section class='card planner-block'><div class='planner-block-head'><div><h2>BALANCE DE LA SEMANA</h2><p>Lo que logré y qué voy a mejorar.</p></div></div>"+renderWeeklyBalance(wr)+"</section></div><div class='planning-col'><section class='card planner-block'><div class='planner-block-head'><div><h2>PRIORIDADES DE LA SEMANA</h2><p>Máximo 3 y siempre dentro de esta semana.</p></div><span class='planner-count'>"+prioritiesFor(d).length+" / 3</span></div>"+renderPlanningPriorities(d)+"</section><section class='card planner-block'><div class='planner-block-head'><div><h2>COSAS POR HACER</h2><p>Pendientes que después puedes asignar a un día.</p></div><button class='outline-btn small' data-action='modal' data-type='task-new' data-no-date='true'>＋ Añadir</button></div>"+renderTodos()+"</section><section class='card planner-block'><div class='planner-block-head'><div><h2>NOTAS / REFLEXIÓN</h2><p>Qué salió bien, qué puedo mejorar, ideas y observaciones.</p></div></div>"+renderWeeklyReflection(wr)+"</section></div><div class='planning-col'><section class='card planner-block'><div class='planner-block-head'><div><h2>METAS A LARGO PLAZO</h2><p>RECUERDA POR QUÉ LO HACES</p></div><button class='outline-btn small' data-action='nav-goals'>Ver metas</button></div>"+renderPlanningGoals()+"</section><section class='card planner-block'><div class='planner-block-head'><div><h2>SEGUIMIENTO SEMANAL</h2><p>Evalúa tu progreso real.</p></div></div>"+renderWeeklyTracking(w)+"</section><div class='planner-belief'>Cree en ti <span>♡</span></div></div></div></div>";}
function renderPlannerDay(d){const k=key(d),r=dayRecord(k),tasks=tasksFor(k),planned=dayHasPlan(k),name=cap(new Intl.DateTimeFormat("es-CL",{weekday:"long"}).format(d));return "<article class='planner-day-card "+(planned?"planned":"")+"'><div class='planner-day-head'><div><span class='day-name'>"+escape(name)+"</span><strong>"+d.getDate()+"</strong></div><button class='day-plan-toggle "+(planned?"active":"")+"' data-action='plan-day-toggle' data-date='"+k+"'>"+(planned?"Planificado":"Planificar")+"</button></div><div class='planner-moods'>"+moodButtonsFor(r)+"</div><div class='planner-task-list'>"+(tasks.length?tasks.map(renderPlannerTask).join(""):"<div class='planner-empty-line'>Añade tareas o marca el día como planificado.</div>")+"</div><button class='add-inline planner-add' data-action='modal' data-type='task-new' data-planned-date='"+k+"'>＋ Añadir tarea</button>"+renderTaskPicker(k)+"</article>";}
function renderPlannerTask(t){return "<div class='planner-task-row "+(t.completed?"done":"pending")+"'><button class='task-check "+(t.completed?"checked":"")+"' data-action='task-toggle' data-id='"+t.id+"'>"+(t.completed?"✓":"")+"</button><div class='planner-task-copy'><strong>"+escape(t.title)+"</strong><small>"+(t.time?escape(t.time):"Sin horario")+(t.priority?" · "+escape(t.priority):"")+"</small></div><button class='row-action' data-action='modal' data-type='task-edit' data-id='"+t.id+"'>✎</button><button class='row-action danger' data-action='task-delete' data-id='"+t.id+"'>×</button></div>";}
function renderTaskPicker(day){const candidates=data.tasks.filter(t=>!t.date||t.date===day);if(!candidates.length)return "<div class='planner-picker empty'><span>No hay tareas disponibles para seleccionar.</span><button class='add-inline' data-action='modal' data-type='task-new' data-planned-date='"+day+"'>＋ Crear tarea</button></div>";return "<div class='planner-picker'><div class='planner-picker-head'><span>Selector de tareas</span><small>3 filas × 2 columnas · desliza horizontalmente</small></div><div class='planner-task-picker-grid'>"+candidates.map(t=>{const selected=t.date===day;const cls=(selected?"selected ":"")+(t.completed?"completed":"available");return "<label class='planner-picker-card "+cls+"'><input type='checkbox' data-action='task-assign' data-id='"+t.id+"' data-day='"+day+"' "+(selected?"checked":"")+"><span class='picker-state'>"+(t.completed?"Completada":selected?"Seleccionada":"Disponible")+"</span><strong>"+escape(t.title)+"</strong><small>"+(t.time?escape(t.time):"Sin horario")+"</small></label>";}).join("")+"</div></div>";}
function renderWeeklyNonneg(w){const ns=data.nonNegotiables.filter(n=>n.active!==false);if(!ns.length)return empty("No hay no negociables configurados.","<button class='add-inline' data-action='modal' data-type='nonneg-new'>＋ Crear no negociable</button>");return "<div class='weekly-nonneg-table'><div class='weekly-nonneg-head'><span>Elemento</span>"+DAY_KEYS.map(x=>"<span>"+x+"</span>").join("")+"</div>"+ns.map(n=>"<div class='weekly-nonneg-row'><strong>"+escape(n.name)+"</strong>"+w.map(d=>{const k=key(d),done=nonnegDone(n,k);return "<button class='tiny-check "+(done?"checked":"")+"' data-action='nonneg-toggle-date' data-id='"+n.id+"' data-date='"+k+"'>"+(done?"✓":"")+"</button>";}).join("")+"</div>").join("")+"</div>";}
function renderPlanningPriorities(d){const list=prioritiesFor(d);if(!list.length)return empty("Define hasta 3 prioridades que representen lo importantede la semana.","<button class='add-inline' data-action='modal' data-type='priority-new'>＋ Crear prioridad</button>");return "<div class='planning-priority-list'>"+list.slice(0,3).map((p,i)=>{const pr=priorityProgress(p);return "<div class='planning-priority-row'><div class='priority-number n"+(i+1)+"'>"+(i+1)+"</div><div><strong>"+escape(p.title)+"</strong>"+bar(pr,i===1?"green":"blue")+"<small>"+(p.taskIds?.length||0)+" tareas relacionadas · "+pr+"%</small></div><button class='text-action' data-action='modal' data-type='priority-edit' data-id='"+p.id+"'>Editar</button></div>";}).join("")+"</div>";}
function renderWeeklyBalance(wr){return "<div class='weekly-form'><label class='field-label'>LO QUE LOGRÉ<textarea data-weekly='balance.achieved' placeholder='¿Qué logré esta semana?'>"+escape(wr.balance?.achieved||"")+"</textarea></label><label class='field-label'>QUÉ VOY A MEJORAR<textarea data-weekly='balance.improve' placeholder='Una mejora concreta para la próxima semana...'>"+escape(wr.balance?.improve||"")+"</textarea></label></div>";}
function renderWeeklyReflection(wr){return "<div class='weekly-form'><label class='field-label'>Qué salió bien<textarea data-weekly='reflection.good'>"+escape(wr.reflection?.good||"")+"</textarea></label><label class='field-label'>Qué puedo mejorar<textarea data-weekly='reflection.improve'>"+escape(wr.reflection?.improve||"")+"</textarea></label><label class='field-label'>Ideas<textarea data-weekly='reflection.ideas'>"+escape(wr.reflection?.ideas||"")+"</textarea></label><label class='field-label'>Observaciones<textarea data-weekly='reflection.observations'>"+escape(wr.reflection?.observations||"")+"</textarea></label></div>";}
function renderPlanningGoals(){if(!data.goals.length)return "<div class='empty-state'><span>Registra una meta para mantener visible tu dirección.</span><button class='add-inline' data-action='modal' data-type='goal-new'>＋ Crear meta</button></div>";return "<div class='planning-goals-list'>"+data.goals.slice(0,4).map(g=>{const p=goalProgress(g);return "<div class='planning-goal-row'><span class='goal-icon'>"+escape(g.icon||"🎯")+"</span><div><strong>"+escape(g.title)+"</strong>"+bar(p,p>=80?"green":"blue")+"</div><b>"+p+"%</b></div>";}).join("")+"<div class='reason-why'><strong>RECUERDA POR QUÉ LO HACES</strong><p>"+escape(data.settings.reasonWhy||"Define en Configuración el motivo que quieres tener presente.")+"</p></div></div>";}
function renderWeeklyTracking(w){const records=w.map(d=>data.days[key(d)]||{}),weights=records.map(r=>Number(r.weight||0)).filter(x=>x>0),steps=records.map(r=>Number(r.steps||0)).filter(x=>x>0),study=records.reduce((s,r)=>s+Number(r.studyMinutes||0),0),sleeps=records.map(r=>Number(r.sleepMinutes||0)).filter(x=>x>0),mood=weekGeneralMood(w),weight=weights.length?avg(weights).toFixed(1)+" kg":"—",avgSteps=steps.length?Math.round(avg(steps)).toLocaleString("es-CL"):"—",sleep=sleeps.length?fmtHours(avg(sleeps)):"—";return "<div class='weekly-tracking'><div><span>PESO</span><b>"+weight+"</b></div><div><span>PASOS PROMEDIO</span><b>"+avgSteps+"</b></div><div><span>HORAS DE ESTUDIO</span><b>"+fmtHours(study)+"</b></div><div><span>HORAS DE SUEÑO</span><b>"+sleep+"</b></div><div><span>SENSACIÓN GENERAL</span><b>"+mood.label+"</b><small>"+(mood.count?mood.count+" día(s) con estado registrado":"sin registros")+"</small></div><div><span>LOGRO DE LA SEMANA</span><b>"+weekCompletion(currentDate())+"%</b></div></div>";}
function renderDay(){
  const d=currentDate(),r=dayRecord(),tasks=tasksFor(state.date),done=tasks.filter(t=>t.completed).length,ns=activeNonneg(),nd=ns.filter(nonnegDone).length,w=week(d),next=getNextAction(d);
  return `<div class="day-layout"><div class="day-main"><section class="hero-card card"><div class="hero-top"><div><div class="eyebrow">ESTADO DEL DÍA</div><h1>${cap(fmtDate(d))}</h1></div><button class="ghost-btn" data-action="modal" data-type="task-new">＋ Nueva tarea</button></div><div class="mood-row"><div class="mood-title">¿Cómo estás hoy?</div>${(r.mood==="Bajo"?MOODS.concat(LEGACY_MOODS):MOODS).map(m=>`<button class="mood-option ${r.mood===m[0]?"selected":""}" data-action="mood" data-mood="${m[0]}"><span>${m[1]}</span><small>${m[0]}</small></button>`).join("")}</div><div class="hero-stats"><div><span>Cumplimiento</span><strong>${dayCompletion()}%</strong></div><div><span>Tareas</span><strong>${done} / ${tasks.length}</strong></div><div><span>No negociables</span><strong>${nd} / ${ns.length}</strong></div><div><span>Energía</span><strong>${r.energy==null?"—":r.energy+" /10"}</strong></div></div><div class="energy-control"><label>Energía <span>opcional</span></label><input type="range" min="1" max="10" value="${r.energy||7}" data-field="energy"><b>${r.energy||7}/10</b></div></section>${section("what","¿Qué hago ahora?","▶",next?escape(next.title):"Todo al día",renderWhatNow(next))}${section("agenda","Agenda del día","▣",`${done} / ${tasks.length} tareas`,renderAgenda(tasks),'<button class="outline-btn small" data-action="modal" data-type="task-new">＋ Nueva tarea</button>')}${section("nonneg","NO NEGOCIABLES","✓",`${nd} / ${ns.length} cumplidos`,renderNonneg(ns),'<button class="outline-btn small" data-action="modal" data-type="nonneg-new">＋ Añadir</button>')}${section("priorities","PRIORIDADES DE LA SEMANA","◎",`${prioritiesFor(d).length} / 3`,renderPriorities(d),'<button class="outline-btn small" data-action="modal" data-type="priority-new">＋ Añadir</button>')}${section("todos","COSAS POR HACER","☷",`${data.tasks.filter(t=>!t.date&&!t.completed).length} pendientes`,renderTodos(),'<button class="outline-btn small" data-action="modal" data-type="task-new" data-no-date="true">＋ Añadir</button>')}${section("habits","HÁBITOS ADICIONALES","▥",`${habitWeekPct(w)}% semanal`,renderHabits(w),'<button class="outline-btn small" data-action="modal" data-type="habit-new">＋ Añadir</button>')}</div><aside class="day-side"><div class="side-stack">${renderRing(dayCompletion(),done,tasks.length,data.habits.filter(h=>habitDone(h,state.date)).length,data.habits.length)}${section("training","Entrenamiento","🏋️",`${trainingWeekCount(w)} / 4`,renderTraining(w),'<button class="outline-btn small" data-action="modal" data-type="training-new">＋ Añadir</button>')}${section("study","Estudio","📚",`${fmtHours(r.studyMinutes)} / ${fmtHours(data.settings.studyGoalMinutes)}`,bar(pct(r.studyMinutes,data.settings.studyGoalMinutes),"green")+`<div class="metric-split"><span>Objetivo</span><b>${fmtMin(data.settings.studyGoalMinutes)}</b></div><div class="quick-input"><input type="number" min="0" step="5" value="${Number(r.studyMinutes||0)}" data-field="studyMinutes"><span>minutos reales</span></div>`)}${section("sleep","Sueño","🌙",`${fmtMin(r.sleepMinutes)} / ${fmtMin(data.settings.sleepGoalMinutes)}`,bar(pct(r.sleepMinutes,data.settings.sleepGoalMinutes),"purple")+`<div class="quick-input"><input type="number" min="0" step="10" value="${Number(r.sleepMinutes||0)}" data-field="sleepMinutes"><span>minutos dormidos</span></div>`)}${section("water","Agua","💧",`${Number(r.waterLiters||0).toFixed(1)} / ${data.settings.waterGoal} L`,bar(pct(r.waterLiters,data.settings.waterGoal))+`<div class="quick-input"><input type="number" min="0" step="0.1" value="${Number(r.waterLiters||0)}" data-field="waterLiters"><span>litros registrados</span></div>`)}${section("min","Plan mínimo · días difíciles","⚡",`${Object.values(r.minimalPlan||{}).filter(Boolean).length} / 4`,renderMinimal(r.minimalPlan))}${section("balance","Balance del día","✎","Se guarda automáticamente",renderDailyBalance(r))}</div></aside></div>`;
}
function getNextAction(d){
  const tasks=tasksFor(key(d)).filter(t=>!t.completed);
  if(!tasks.length)return data.tasks.find(t=>!t.date&&!t.completed)||null;
  const now=new Date(),nowM=now.getHours()*60+now.getMinutes();
  return tasks.map(t=>{
    const tm=minutesFromTime(t.time),priority=t.priority==="alta"?5:t.priority==="media"?3:1;
    const overdue=tm!==null&&key(d)===todayKey()&&tm<nowM?6:0;
    const near=tm===null?0:Math.max(0,180-Math.abs(tm-nowM))/60;
    const short=Math.max(0,60-Math.min(60,Number(t.estimatedMinutes)||60))/100;
    return {t,score:priority+overdue+near+short};
  }).sort((a,b)=>b.score-a.score||(minutesFromTime(a.t.time)??9999)-(minutesFromTime(b.t.time)??9999))[0].t;
}
function getFollowingAction(t){return tasksFor(state.date).filter(x=>!x.completed&&x.id!==t.id).sort((a,b)=>(minutesFromTime(a.time)??9999)-(minutesFromTime(b.time)??9999))[0]||data.tasks.find(x=>!x.date&&!x.completed)||null}
function renderWhatNow(next){if(!next)return empty("No hay una acción pendiente. Puedes planificar una tarea o cerrar el día con calma.");const f=getFollowingAction(next);return `<div class="now-grid"><div class="now-main"><div class="kicker">AHORA</div><div class="now-title">${escape(next.title)}</div><div class="now-meta">${next.time?`${next.time} – ${timeEnd(next.time,next.estimatedMinutes||60)}`:"Sin horario"}</div><span class="priority-pill ${next.priority||"baja"}">Prioridad ${next.priority||"baja"}</span><button class="primary-btn" data-action="task-toggle" data-id="${next.id}">Marcar completada</button></div><div class="now-next"><div class="kicker">SIGUIENTE</div><strong>${escape(f?.title||"Nada pendiente")}</strong><span>Continúa con la siguiente acción disponible.</span></div></div>`}
function renderAgenda(tasks){if(!tasks.length)return empty("Este día todavía no tiene tareas.",'<button class="add-inline" data-action="modal" data-type="task-new">＋ Agregar tarea</button>');return `<div class="task-list">${[...tasks].sort((a,b)=>(a.time||"99:99").localeCompare(b.time||"99:99")).map(taskRow).join("")}</div><button class="add-inline" data-action="modal" data-type="task-new">＋ Agregar tarea</button>`}
function taskRow(t){return `<div class="task-row ${t.completed?"done":""}"><button class="task-check ${t.completed?"checked":""}" data-action="task-toggle" data-id="${t.id}">${t.completed?"✓":""}</button><div class="task-time">${escape(t.time||"—")}</div><div class="task-title-wrap"><strong>${escape(t.title)}</strong>${t.note?`<small>${escape(t.note)}</small>`:""}${!t.date&&t.createdAt?`<small>${pendingAge(t.createdAt)}</small>`:""}</div>${t.priority?`<span class="priority-pill subtle ${t.priority}">${t.priority}</span>`:"<span></span>"}<button class="row-action" data-action="modal" data-type="task-edit" data-id="${t.id}">✎</button><button class="row-action" data-action="task-tomorrow" data-id="${t.id}">→</button><button class="row-action danger" data-action="task-delete" data-id="${t.id}">×</button></div>`}
function pendingAge(createdAt){const diff=Math.max(0,Math.floor((parse(state.date)-parse(createdAt))/86400000));return diff===0?"Pendiente hoy":`Pendiente desde hace ${diff} día${diff===1?"":"s"}`}
function renderNonneg(ns){if(!ns.length)return empty("Aún no defines tus no negociables.",'<button class="add-inline" data-action="modal" data-type="nonneg-new">＋ Crear no negociable</button>');const r=dayRecord();return `<div class="nonneg-list">${ns.map(n=>{const done=nonnegDone(n),v=n.mode==="water"?`${Number(r.waterLiters||0).toFixed(1)} / ${data.settings.waterGoal} L`:n.mode==="study"?`${fmtHours(r.studyMinutes)} / ${fmtHours(data.settings.studyGoalMinutes)}`:n.mode==="sleep"?`${fmtMin(r.sleepMinutes)} / ${fmtMin(data.settings.sleepGoalMinutes)}`:done?"✓":"Pendiente";return `<div class="metric-row"><span class="metric-icon">${escape(n.icon||"✓")}</span><div class="metric-copy"><strong>${escape(n.name)}</strong><small>${escape(n.target||"Acuerdo personal")}</small></div><div class="metric-value">${v}</div><button class="tiny-check ${done?"checked":""}" data-action="nonneg-toggle" data-id="${n.id}">${done?"✓":""}</button><button class="row-action" data-action="modal" data-type="nonneg-edit" data-id="${n.id}">✎</button></div>`}).join("")}</div>`}
function renderPriorities(d){const list=prioritiesFor(d);if(!list.length)return empty("Define hasta 3 prioridades que representen lo importante de la semana.",'<button class="add-inline" data-action="modal" data-type="priority-new">＋ Crear prioridad</button>');return `<div class="priority-list">${list.slice(0,3).map((p,i)=>{const pr=priorityProgress(p);return `<div class="priority-row"><div class="priority-number n${i+1}">${i+1}</div><div class="priority-copy"><strong>${escape(p.title)}</strong>${bar(pr,i===1?"green":"blue")}<small class="related-count">${p.taskIds?.length||0} tareas relacionadas</small></div><span>${pr}%</span><button class="text-action" data-action="modal" data-type="priority-edit" data-id="${p.id}">Editar</button></div>`}).join("")}</div>`}
function renderTodos(){const list=data.tasks.filter(t=>!t.date&&!t.completed);return list.length?`<div class="task-list compact">${list.map(taskRow).join("")}</div>`:empty("Tu bandeja de pendientes está limpia.",'<button class="add-inline" data-action="modal" data-type="task-new" data-no-date="true">＋ Agregar pendiente</button>')}
function renderHabits(w){if(!data.habits.length)return empty("Aún no tienes hábitos adicionales.",'<button class="add-inline" data-action="modal" data-type="habit-new">＋ Crear hábito</button>');return `<div class="habit-table-wrap"><table class="habit-table"><thead><tr><th>Hábito</th>${DAY_KEYS.map(x=>`<th>${x}</th>`).join("")}<th>%</th><th></th></tr></thead><tbody>${data.habits.map(h=>`<tr><td><strong>${escape(h.name)}</strong><small>${escape(h.target||"")}</small></td>${w.map((d,i)=>{const k=key(d),scheduled=habitScheduled(h,d),on=habitDone(h,k);return `<td>${scheduled?`<button class="habit-check ${on?"checked":""}" data-action="habit-toggle" data-id="${h.id}" data-date="${k}">${on?"✓":""}</button>`:'<span class="habit-na">—</span>'}</td>`}).join("")}<td>${habitWeekPctFor(h,w)}%</td><td><button class="row-action" data-action="modal" data-type="habit-edit" data-id="${h.id}">✎</button><button class="row-action danger" data-action="habit-delete" data-id="${h.id}">×</button></td></tr>`).join("")}</tbody></table></div>`}
function renderTraining(w){const list=data.training.filter(t=>w.some(d=>key(d)===t.date));if(!list.length)return empty("No hay entrenamientos registrados para esta semana.",'<button class="add-inline" data-action="modal" data-type="training-new">＋ Añadir entrenamiento</button>');return `<div class="training-list">${[...list].sort((a,b)=>a.date.localeCompare(b.date)).map(t=>`<div class="training-row"><button class="tiny-check ${t.completed?"checked":""}" data-action="training-toggle" data-id="${t.id}">${t.completed?"✓":""}</button><div><strong>${escape(t.title)}</strong><small>${escape(fmtShortDate(parse(t.date)))} · ${escape(t.time||"—")} · ${Number(t.durationMinutes||0)} min · ${escape(t.type||"General")}${t.perception?" · "+escape(t.perception):""}</small></div><button class="text-action" data-action="modal" data-type="training-edit" data-id="${t.id}">Editar</button></div>`).join("")}</div>`}
function renderRing(c,done,total,hd,ht){return `<div class="card mini-card summary-ring"><div class="mini-head"><strong>Cumplimiento del día</strong><span>${c}%</span></div><div class="ring" style="--value:${c*3.6}deg"><span>${c}%</span></div><div class="ring-note">Tareas ${done}/${total} · Hábitos ${hd}/${ht}</div></div>`}
function renderMinimal(m){return `<div class="minimal-list">${[["study","30 min de estudio"],["water","Agua"],["training","Entrenamiento"],["sleep","Dormir antes de 00:00"]].map(([k,l])=>`<button class="minimal-row" data-action="minimal-toggle" data-key="${k}"><span class="task-check ${m?.[k]?"checked":""}">${m?.[k]?"✓":""}</span>${l}</button>`).join("")}</div><div class="support-note">♡ Hoy no necesitas hacerlo todo.<br>Cumple lo esencial.</div>`}
function renderDailyBalance(r){return `<label class="field-label">Lo que logré<textarea data-reflection="achieved" placeholder="¿Qué salió bien hoy?">${escape(r.reflection?.achieved||"")}</textarea></label><label class="field-label">Qué voy a mejorar<textarea data-reflection="improve" placeholder="Una mejora concreta para mañana...">${escape(r.reflection?.improve||"")}</textarea></label><label class="field-label">Notas<textarea data-reflection="notes" placeholder="Ideas, observaciones o recordatorios">${escape(r.reflection?.notes||"")}</textarea></label>`}
function renderWeek(){const w=week(currentDate()),tasks=weekTasks(currentDate()),done=tasks.filter(t=>t.completed).length,study=w.reduce((s,d)=>s+Number(data.days[key(d)]?.studyMinutes||0),0),sleep=w.map(d=>Number(data.days[key(d)]?.sleepMinutes||0)).filter(v=>v>0);return `<div class="view-stack"><div class="page-heading"><div><span class="eyebrow">SEMANA ${weekNumber(currentDate())}</span><h1>${escape(weekLabel(currentDate()))}</h1><p>Revisa lo registrado y entra a cualquier día para ejecutar.</p></div><button class="primary-btn" data-action="modal" data-type="priority-new">＋ Prioridad</button></div><div class="week-summary-grid">${metricCard("Cumplimiento general",weekCompletion(currentDate())+"%",weekCompletion(currentDate()))}${metricCard("Tareas",done+" / "+tasks.length,pct(done,tasks.length))}${metricCard("Entrenamientos",trainingWeekCount(w)+" / 4",pct(trainingWeekCount(w),4),"green")}${metricCard("Estudio",fmtHours(study),pct(study,data.settings.studyGoalMinutes*7),"purple")}</div><div class="week-day-grid">${w.map(daySummary).join("")}</div><div class="two-col">${renderWeekDetails(w)}${renderWeekBalanceLegacy(w[0])}</div></div>`}
function metricCard(title,value,p,tone="blue"){return `<div class="card metric-card"><span>${escape(title)}</span><strong>${escape(value)}</strong>${bar(p,tone)}</div>`}
function daySummary(d){const k=key(d),ts=tasksFor(k),done=ts.filter(t=>t.completed).length,r=data.days[k],m=MOODS.find(x=>x[0]===r?.mood),tr=data.training.some(t=>t.date===k&&t.completed);return `<button class="day-summary-card ${k===state.date?"today":""}" data-action="go-date" data-date="${k}"><div class="day-name">${cap(new Intl.DateTimeFormat("es-CL",{weekday:"short"}).format(d).replace(".",""))}</div><div class="day-num">${d.getDate()}</div><div class="day-task-count">${done}/${ts.length} tareas</div><div class="day-score">${dayCompletion(k)}%</div><div class="day-dots"><span class="dot task ${done?"active":""}"></span><span class="dot habit ${dayHabitPct(k)>0?"active":""}"></span><span class="dot train ${tr?"active":""}"></span></div>${m?`<span class="day-mood">${m[1]}</span>`:'<span class="day-mood muted">—</span>'}</button>`}
function renderWeekDetails(w){const ts=weekTasks(currentDate()),done=ts.filter(t=>t.completed).length,nsTotal=w.reduce((s,d)=>s+activeNonneg(key(d)).length,0),nsDone=w.reduce((s,d)=>s+activeNonneg(key(d)).filter(n=>nonnegDone(n,key(d))).length,0),study=w.reduce((s,d)=>s+Number(data.days[key(d)]?.studyMinutes||0),0),sl=w.map(d=>Number(data.days[key(d)]?.sleepMinutes||0)).filter(v=>v>0);return `<section class="card detail-panel"><div class="panel-heading"><div><h3>Resumen de la semana</h3><small>Datos registrados.</small></div></div><div class="stats-table"><div><span>Tareas completadas</span><b>${done} / ${ts.length}</b></div><div><span>No negociables</span><b>${nsDone} / ${nsTotal}</b></div><div><span>Hábitos</span><b>${habitWeekPct(w)}%</b></div><div><span>Entrenamientos</span><b>${trainingWeekCount(w)} / 4</b></div><div><span>Estudio</span><b>${fmtHours(study)}</b></div><div><span>Sueño promedio</span><b>${sl.length?fmtMin(Math.round(avg(sl))):"—"}</b></div></div></section>`}
function renderWeekBalanceLegacy(firstDay){const wk=key(startWeek(firstDay)),b=ensureWeek(data,wk);return `<section class="card detail-panel"><div class="panel-heading"><div><h3>BALANCE DE LA SEMANA</h3><small>Semana ${escape(weekLabel(parse(wk)))}</small></div></div><label class="field-label">LO QUE LOGRÉ<textarea data-weekly="balance.achieved" placeholder="Qué salió bien...">${escape(b.balance?.achieved||"")}</textarea></label><label class="field-label">QUÉ VOY A MEJORAR<textarea data-weekly="balance.improve" placeholder="Qué cambiaré...">${escape(b.balance?.improve||"")}</textarea></label></section>`}
function renderMonth(){const a=parse(state.month),cells=monthGrid(a),days=cells.filter(d=>d.getMonth()===a.getMonth()),mc=days.length?Math.round(avg(days.map(d=>dayCompletion(key(d))))):0,ts=days.flatMap(tasksFor),tp=pct(ts.filter(t=>t.completed).length,ts.length),tr=data.training.filter(t=>t.completed&&t.date.startsWith(state.month.slice(0,7))).length;return `<div class="view-stack"><div class="page-heading"><div><span class="eyebrow">MES</span><h1>${cap(fmtMonth(a))}</h1><p>Selecciona un día para entrar a su planificación.</p></div><div class="month-nav"><button class="outline-btn" data-action="month-nav" data-delta="-1">←</button><button class="outline-btn" data-action="month-nav" data-delta="1">→</button></div></div><div class="month-month-summary><div><span>Cumplimiento medio</span><b>${mc}%</b></div><div><span>Tareas</span><b>${tp}%</b></div><div><span>Entrenamientos</span><b>${tr}</b></div><div><span>Hábitos</span><b>${monthlyHabitPct(a)}%</b></div></div><section class="card month-card"><div class="calendar-week-head">${DAY_KEYS.map(x=>`<span>${x}</span>`).join("")}</div><div class="calendar-grid">${cells.map(d=>{const k=key(d),inside=d.getMonth()===a.getMonth(),t=tasksFor(k),c=dayCompletion(k),h=data.habits.some(x=>habitDone(x,k)),x=data.training.some(z=>z.date===k&&z.completed);return `<button class="calendar-day ${inside?"":"muted"} ${k===state.date?"selected":""}" data-action="go-date" data-date="${k}"><span class="calendar-num">${d.getDate()}</span><span class="calendar-score">${c}%</span><div class="calendar-meta"><i class="task ${t.some(z=>z.completed)?"on":""}"></i><i class="habit ${h?"on":""}"></i><i class="train ${x?"on":""}"></i></div><small>${t.filter(z=>z.completed).length}/${t.length}</small></button>`}).join("")}</div></section></div>`}
function monthlyHabitPct(a){const ds=monthGrid(a).filter(d=>d.getMonth()===a.getMonth());let total=0,done=0;for(const h of data.habits)for(const d of ds)if(habitScheduled(h,d)){total++;if(habitDone(h,key(d)))done++;}return pct(done,total)}
function toggleNonnegForDate(n,date){
  const k=key(parse(date));
  if(n.mode==="water")return setData(d=>{const r=ensureDay(d,k);r.waterLiters=nonnegDone(n,k)?0:d.settings.waterGoal;return d;});
  if(n.mode==="study")return setData(d=>{const r=ensureDay(d,k);r.studyMinutes=nonnegDone(n,k)?0:d.settings.studyGoalMinutes;return d;});
  if(n.mode==="sleep")return setData(d=>{const r=ensureDay(d,k);r.sleepMinutes=nonnegDone(n,k)?0:d.settings.sleepGoalMinutes;return d;});
  if(n.mode==="training"){const slot=Number(n.slot)||1;const ex=data.training.find(t=>t.date===k&&Number(t.slot)===slot);if(ex)return setData(d=>({...d,training:d.training.map(t=>t.id===ex.id?{...t,completed:!t.completed}:t)}));return setData(d=>({...d,training:[...d.training,{id:id("training"),title:"Entrenamiento "+slot,slot,date:k,time:"19:00",durationMinutes:60,type:"General",completed:true}]}));}
  return setData(d=>({...d,nonNegotiables:d.nonNegotiables.map(x=>x.id===n.id?{...x,checks:{...(x.checks||{}),[k]:!nonnegDone(n,k)}}:x)}));
}
function renderGoals(){return `<div class="view-stack"><div class="page-heading"><div><span class="eyebrow">METAS</span><h1>Metas a largo plazo</h1><p>Meta → prioridad → tarea → completado.</p></div><button class="primary-btn" data-action="modal" data-type="goal-new">＋ Añadir meta</button></div>${data.goals.length?`<div class="goal-grid">${data.goals.map(g=>{const p=goalProgress(g);return `<div class="card goal-card"><div class="goal-icon">${escape(g.icon||"🎯")}</div><div class="goal-copy"><small>${escape(g.category||"Personal")}</small><h3>${escape(g.title)}</h3>${bar(p,p>=80?"green":"blue")}</div><strong>${p}%</strong><div class="goal-links"><span>${g.priorityIds?.length||0} prioridades</span><span>${g.taskIds?.length||0} tareas</span><span>${g.habitIds?.length||0} hábitos</span><button class="text-action" data-action="modal" data-type="goal-edit" data-id="${g.id}">Editar</button><button class="row-action danger" data-action="goal-delete" data-id="${g.id}">×</button></div></div>`}).join("")}</div>`:empty("Todavía no tienes metas.",'<button class="add-inline" data-action="modal" data-type="goal-new">＋ Crear meta</button>')}<div class="card chain-card"><h3>La cadena que importa</h3><div class="chain"><span>META</span><b>↓</b><span>PRIORIDAD</span><b>↓</b><span>TAREA</span><b>↓</b><span>COMPLETADO</span></div></div></div>`}
function renderProgress(){const base=startWeek(currentDate()),ws=[3,2,1,0].map(i=>week(add(base,-i*7))),labels=["Cumplimiento","Hábitos","Entrenamiento","Estudio","Sueño","Pasos","Peso"];return `<div class="view-stack"><div class="page-heading"><div><span class="eyebrow">PROGRESO</span><h1>Tu evolución</h1><p>4 semanas centradas en la semana seleccionada.</p></div></div><div class="trend-grid">${labels.map(l=>trendCard(l,ws)).join("")}</div><div class="card history-card"><div class="panel-heading"><div><h3>Historial reciente</h3><small>Semana de referencia: ${escape(weekLabel(currentDate()))}</small></div></div><div class="history-list">${ws.map(w=>`<div><strong>Semana ${weekNumber(w[3])}</strong><span>${weekLabel(w[3])}</span><b>${weekCompletion(w[3])}%</b></div>`).join("")}</div></div></div>`}
function weekMetric(w,l){if(l==="Cumplimiento")return weekCompletion(w[3]);if(l==="Hábitos")return habitWeekPct(w);if(l==="Entrenamiento")return pct(data.training.filter(t=>t.completed&&w.some(d=>key(d)===t.date)).length,4);const rs=w.map(d=>data.days[key(d)]).filter(Boolean);if(l==="Estudio")return pct(rs.reduce((s,r)=>s+Number(r.studyMinutes||0),0),data.settings.studyGoalMinutes*7);if(l==="Sueño"){const v=rs.map(r=>Number(r.sleepMinutes||0)).filter(x=>x>0);return pct(v.length?avg(v):0,data.settings.sleepGoalMinutes)}if(l==="Pasos"){const v=rs.map(r=>Number(r.steps||0)).filter(x=>x>0);return pct(v.length?avg(v):0,data.settings.stepsGoal)}const v=rs.map(r=>Number(r.weight||0)).filter(x=>x>0);return v.length?avg(v):0}
function trendCard(l,ws){const vals=ws.map(w=>weekMetric(w,l)),latest=vals[vals.length-1]||0;return `<div class="card trend-card"><div class="trend-top"><div><small>${l}</small><strong>${l==="Peso"?(latest?latest.toFixed(1)+" kg":"—"):Math.round(latest)+"%"}</strong></div><span>4 semanas</span></div><div class="sparkline"><svg viewBox="0 0 220 70"><polyline points="${spark(vals)}" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg></div><div class="trend-note">Basado únicamente en registros guardados.</div></div>`}
function spark(v){if(v.length<2)return"0,54 220,54";const min=Math.min(...v),max=Math.max(...v),span=max-min||1;return v.map((x,i)=>(i/(v.length-1))*220+","+(58-((x-min)/span)*46)).join(" ")}
function renderInsights(){const ks=Object.keys(data.days).sort();if(ks.length<3)return `<div class="view-stack"><div class="page-heading"><div><span class="eyebrow">MIS PATRONES</span><h1>Insights</h1><p>Necesitamos varios registros antes de comparar.</p></div></div><div class="card note-card"><strong>Empieza registrando varios días.</strong><p>Con al menos 3 días con datos aparecerán observaciones descriptivas.</p></div></div>`;const wd=DAY_NUMS.map(n=>{const vals=ks.filter(k=>parse(k).getDay()===n).map(dayCompletion);return{n,score:avg(vals),count:vals.length}}).filter(x=>x.count).sort((a,b)=>b.score-a.score),best=wd[0];const d0=new Date(2026,0,4+(best?.n||0)),s7=ks.filter(k=>Number(data.days[k].sleepMinutes||0)>=420),sl=ks.filter(k=>Number(data.days[k].sleepMinutes||0)>0&&Number(data.days[k].sleepMinutes||0)<420),a7=s7.length?Math.round(avg(s7.map(dayCompletion))):null,al=sl.length?Math.round(avg(sl.map(dayCompletion))):null;return `<div class="view-stack"><div class="page-heading"><div><span class="eyebrow">MIS PATRONES</span><h1>Insights</h1><p>Observaciones descriptivas; no implican causalidad.</p></div></div><div class="insight-grid"><div class="card insight-card"><div class="insight-icon">↗</div><div><h3>Día con mayor cumplimiento</h3><p>${best?cap(new Intl.DateTimeFormat("es-CL",{weekday:"long"}).format(d0))+" presenta el promedio más alto ("+Math.round(best.score)+"%).":"Aún no hay suficientes comparaciones."}</p></div></div><div class="card insight-card"><div class="insight-icon">◔</div><div><h3>Sueño y cumplimiento</h3><p>${a7!==null?"En los días con 7 h o más registraste "+a7+"% de cumplimiento medio. "+(al!==null?"En los días con menos de 7 h fue "+al+"%.":""):"Todavía no hay suficientes registros comparables de sueño."}</p></div></div><div class="card insight-card"><div class="insight-icon">🏋️</div><div><h3>Entrenamiento</h3><p>Has registrado ${data.training.filter(t=>t.completed).length} entrenamiento(s) completado(s) en total.</p></div></div><div class="card insight-card"><div class="insight-icon">📋</div><div><h3>Bandeja pendiente</h3><p>Tienes ${data.tasks.filter(t=>!t.date&&!t.completed).length} tarea(s) sin fecha y sin completar.</p></div></div></div><div class="card note-card"><strong>Cómo leer estos insights</strong><p>PLAN 2.0 describe coincidencias de tus registros y no afirma que una variable cause otra.</p></div></div>`}
function renderSettings(){const n="Notification"in window,sw="serviceWorker"in navigator,secure=location.protocol==="https:"||location.hostname==="localhost"||location.hostname==="127.0.0.1";return `<div class="view-stack"><div class="page-heading"><div><span class="eyebrow">CONFIGURACIÓN</span><h1>Configura lo necesario</h1><p>Datos locales, PWA, notificaciones y sincronización.</p></div></div><div class="settings-grid"><div class="card"><h3>Objetivos</h3><label class="field-label">Agua (L)<input type="number" min="0" step="0.1" value="${data.settings.waterGoal}" data-setting="waterGoal"></label><label class="field-label">Estudio (min)<input type="number" min="0" step="5" value="${data.settings.studyGoalMinutes}" data-setting="studyGoalMinutes"></label><label class="field-label">Sueño objetivo (min)<input type="number" min="0" step="10" value="${data.settings.sleepGoalMinutes}" data-setting="sleepGoalMinutes"></label><label class="field-label">Pasos objetivo<input type="number" min="0" step="500" value="${data.settings.stepsGoal}" data-setting="stepsGoal"></label></div><div class="card"><h3>Notificaciones</h3><p class="settings-copy">Notifications API: ${n?Notification.permission:"no disponible"}<br>Service Worker: ${sw?"disponible":"no disponible"}<br>Entorno seguro: ${secure?"sí":"no"}</p><div class="settings-actions"><button class="primary-btn" data-action="notification-enable">${data.notifications.enabled?"Notificaciones activas":"Activar notificaciones"}</button><button class="outline-btn" data-action="notification-test">Probar</button></div><label class="field-label">Avisar antes (min)<input type="number" min="0" max="120" step="5" value="${data.notifications.leadMinutes}" data-setting-notification="leadMinutes"></label><label class="minimal-row"><input type="checkbox" data-setting-notification="overdue" ${data.notifications.overdue?"checked":""}> Avisar por tareas vencidas</label><div class="support-note">Los recordatorios locales se ejecutan mientras la aplicación está activa. Web Push con la app cerrada requiere un servidor.</div></div><div class="card"><h3>PWA</h3><p class="settings-copy">Manifest, iconos, service worker, instalación y caché offline están incluidos.</p><button class="outline-btn" data-action="install-pwa">${state.deferredInstallPrompt?"Instalar PLAN 2.0":"Instalar / añadir a inicio"}</button><div class="support-note">En Android usa “Instalar app” o “Añadir a pantalla de inicio”.</div></div><div class="card"><h3>Sincronización</h3><p class="settings-copy">Entre pestañas: ${"BroadcastChannel"in window?"activa":"no disponible"}. Para distintos dispositivos puedes configurar un endpoint REST.</p><label class="minimal-row"><input type="checkbox" data-sync-setting="enabled" ${data.sync.enabled?"checked":""}> Activar sincronización remota</label><label class="field-label">Endpoint REST<input type="url" placeholder="https://tu-servidor.example/sync" value="${escape(data.sync.endpoint||"")}" data-sync-setting="endpoint"></label><label class="field-label">Token<input type="password" value="${escape(data.sync.token||"")}" data-sync-setting="token"></label><div class="settings-actions"><button class="outline-btn" data-action="sync-now">Sincronizar ahora</button><button class="outline-btn" data-action="export">Exportar respaldo</button><label class="outline-btn file-button">Importar respaldo<input type="file" accept="application/json" data-action="import"></label></div><small class="settings-copy">Última sincronización: ${escape(data.sync.lastSync||"nunca")}</small></div><div class="card"><h3>Datos</h3><p class="settings-copy">La versión comienza vacía y usa una clave v2, separada de la antigua demo.</p><button class="outline-btn" data-action="reset">Restaurar PLAN 2.0 vacío</button></div></div></div>`}
function findItem(type,itemId){const map={task:data.tasks,habit:data.habits,priority:data.priorities,training:data.training,goal:data.goals,nonneg:data.nonNegotiables};const e=Object.entries(map).find(([k])=>type.startsWith(k));return e?.[1].find(x=>x.id===itemId)||null}
function renderModal(){
  const m=state.modal,t=m.type,item=findItem(t,m.id),task=t.startsWith("task"),habit=t.startsWith("habit"),priority=t.startsWith("priority"),training=t.startsWith("training"),goal=t.startsWith("goal"),non=t.startsWith("nonneg");
  let title=task?(m.id?"Editar tarea":"Nueva tarea"):habit?(m.id?"Editar hábito":"Nuevo hábito"):priority?(m.id?"Editar prioridad":"Nueva prioridad"):training?(m.id?"Editar entrenamiento":"Nuevo entrenamiento"):goal?(m.id?"Editar meta":"Nueva meta"):(m.id?"Editar no negociable":"Nuevo no negociable"),body="";
  if(task){
    body=`<label class="field-label">Título<input data-form="title" value="${escape(item?.title||"")}" autofocus></label><div class="form-grid"><label class="field-label">Fecha<input type="date" data-form="date" value="${escape(item?.date||state.date)}"></label><label class="field-label">Hora<input type="time" data-form="time" value="${escape(item?.time||"")}"></label></div><label class="minimal-row"><input type="checkbox" data-form="noDate" ${(m.noDate||!item?.date)?"checked":""}> Guardar sin fecha (pendiente)</label><div class="form-grid"><label class="field-label">Prioridad<select data-form="priority"><option value="alta" ${item?.priority==="alta"?"selected":""}>Alta</option><option value="media" ${!item?.priority||item?.priority==="media"?"selected":""}>Media</option><option value="baja" ${item?.priority==="baja"?"selected":""}>Baja</option></select></label><label class="field-label">Duración (min)<input type="number" min="0" step="5" data-form="estimatedMinutes" value="${item?.estimatedMinutes||60}"></label></div><label class="field-label">Prioridad semanal<select data-form="priorityId"><option value="">— Ninguna —</option>${prioritiesFor(currentDate()).map(p=>`<option value="${p.id}" ${item?.priorityId===p.id?"selected":""}>${escape(p.title)}</option>`).join("")}</select></label><label class="field-label">Meta relacionada<select data-form="goalId"><option value="">— Ninguna —</option>${data.goals.map(g=>`<option value="${g.id}" ${item?.goalId===g.id?"selected":""}>${escape(g.title)}</option>`).join("")}</select></label><label class="field-label">Nota<textarea data-form="note">${escape(item?.note||"")}</textarea></label>`;
  }else if(habit){
    const days=item?.daysOfWeek||DAY_NUMS;
    body=`<label class="field-label">Nombre<input data-form="name" value="${escape(item?.name||"")}" autofocus></label><label class="field-label">Objetivo<input data-form="target" value="${escape(item?.target||"")}" placeholder="Ej. 20 min"></label><label class="field-label">Frecuencia<select data-form="frequency"><option value="daily" ${item?.frequency!=="weekly"?"selected":""}>Diaria</option><option value="weekly" ${item?.frequency==="weekly"?"selected":""}>Semanal</option></select></label><div class="field-label">Días activos<div class="weekday-picks">${DAY_NUMS.map((n,i)=>`<label><input type="checkbox" data-habit-day="${n}" ${days.includes(n)?"checked":""}> ${DAY_KEYS[i]}</label>`).join("")}</div></div>`;
  }else if(priority){
    const tids=item?.taskIds||[];
    body=`<label class="field-label">Prioridad<input data-form="title" value="${escape(item?.title||"")}" autofocus></label><label class="field-label">Progreso base <span id="range-output">${item?.progress||0}%</span><input type="range" min="0" max="100" value="${item?.progress||0}" data-form="progress" data-range-output="range-output"></label><div class="field-label">Tareas relacionadas<div class="checklist-picks">${tasksFor(currentDate()).map(x=>`<label><input type="checkbox" data-priority-task="${x.id}" ${tids.includes(x.id)?"checked":""}> ${escape(x.title)}</label>`).join("")}</div></div>`;
  }else if(training){
    body=`<label class="field-label">Nombre<input data-form="title" value="${escape(item?.title||"")}" autofocus></label><div class="form-grid"><label class="field-label">Fecha<input type="date" data-form="date" value="${escape(item?.date||state.date)}"></label><label class="field-label">Hora<input type="time" data-form="time" value="${escape(item?.time||"19:00")}"></label></div><div class="form-grid"><label class="field-label">Duración (min)<input type="number" min="0" data-form="durationMinutes" value="${item?.durationMinutes||60}"></label><label class="field-label">Tipo<input data-form="type" value="${escape(item?.type||"Fuerza")}"></label></div><label class="field-label">Percepción general<input data-form="perception" value="${escape(item?.perception||"")}" placeholder="Ej. Bien, cansado, fácil..."></label><label class="minimal-row"><input type="checkbox" data-form="completed" ${item?.completed?"checked":""}> Marcar como completado</label><label class="field-label">Notas<textarea data-form="note">${escape(item?.note||"")}</textarea></label>`;
  }else if(goal){
    const pids=item?.priorityIds||[],tids=item?.taskIds||[],hids=item?.habitIds||[];
    body=`<div class="form-grid"><label class="field-label">Icono<input data-form="icon" value="${escape(item?.icon||"🎯")}"></label><label class="field-label">Categoría<input data-form="category" value="${escape(item?.category||"Personal")}"></label></div><label class="field-label">Meta<input data-form="title" value="${escape(item?.title||"")}" autofocus></label><label class="field-label">Progreso base <span id="range-output">${item?.progress||0}%</span><input type="range" min="0" max="100" value="${item?.progress||0}" data-form="progress" data-range-output="range-output"></label><label class="field-label">Fecha objetivo<input type="date" data-form="targetDate" value="${escape(item?.targetDate||"")}"></label><div class="field-label">Prioridades relacionadas<div class="checklist-picks">${prioritiesFor(currentDate()).map(p=>`<label><input type="checkbox" data-goal-priority="${p.id}" ${pids.includes(p.id)?"checked":""}> ${escape(p.title)}</label>`).join("")}</div></div><div class="field-label">Tareas relacionadas<div class="checklist-picks">${data.tasks.filter(x=>x.date).map(x=>`<label><input type="checkbox" data-goal-task="${x.id}" ${tids.includes(x.id)?"checked":""}> ${escape(x.title)}</label>`).join("")}</div></div><div class="field-label">Hábitos relacionados<div class="checklist-picks">${data.habits.map(h=>`<label><input type="checkbox" data-goal-habit="${h.id}" ${hids.includes(h.id)?"checked":""}> ${escape(h.name)}</label>`).join("")}</div></div>`;
  }else if(non){
    const days=item?.days||DAY_NUMS;
    body=`<div class="form-grid"><label class="field-label">Icono<input data-form="icon" value="${escape(item?.icon||"✓")}"></label><label class="field-label">Objetivo<input data-form="target" value="${escape(item?.target||"Diario")}"></label></div><label class="field-label">Nombre<input data-form="name" value="${escape(item?.name||"")}" autofocus></label><div class="form-grid"><label class="field-label">Qué mide<select data-form="mode"><option value="manual" ${!item?.mode||item?.mode==="manual"?"selected":""}>Marcación manual</option><option value="water" ${item?.mode==="water"?"selected":""}>Agua</option><option value="study" ${item?.mode==="study"?"selected":""}>Estudio</option><option value="sleep" ${item?.mode==="sleep"?"selected":""}>Sueño</option><option value="training" ${item?.mode==="training"?"selected":""}>Entrenamiento</option></select></label><label class="minimal-row"><input type="checkbox" data-form="active" ${item?.active!==false?"checked":""}> Activo</label></div><label class="field-label">ENTRENAMIENTO<select data-form="slot"><option value="1" ${Number(item?.slot||1)===1?"selected":""}>1</option><option value="2" ${Number(item?.slot)===2?"selected":""}>2</option><option value="3" ${Number(item?.slot)===3?"selected":""}>3</option><option value="4" ${Number(item?.slot)===4?"selected":""}>4</option></select></label><div class="field-label">Días activos<div class="weekday-picks">${DAY_NUMS.map((n,i)=>`<label><input type="checkbox" data-nonneg-day="${n}" ${days.includes(n)?"checked":""}> ${DAY_KEYS[i]}</label>`).join("")}</div></div>`;
  }
  return `<div class="modal-backdrop" data-action="close-modal"><div class="modal card" data-modal-inner><div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="close-modal">×</button></div>${body}<div class="modal-actions"><button class="outline-btn" data-action="close-modal">Cancelar</button><button class="primary-btn" data-action="modal-save">Guardar</button></div></div></div>`;
}
function modalForm(){const q={};document.querySelectorAll("[data-form]").forEach(el=>q[el.dataset.form]=el.type==="checkbox"?el.checked:el.value);return q}
function saveModal(){
  const m=state.modal,t=m.type,f=modalForm(),itemId=m.id;
  let savedTaskId=itemId||null,savedTaskDate=null,savedTrainingDate=null;
  if(t==="task-new"||t==="task-edit"){
    const noDate=!!f.noDate,old=itemId?findItem(t,itemId):null,obj={title:(f.title||"").trim()||"Nueva tarea",date:noDate?"":(f.date||m.plannedDate||state.date),time:f.time||"",priority:f.priority||"media",note:f.note||"",estimatedMinutes:Number(f.estimatedMinutes)||60,priorityId:f.priorityId||"",goalId:f.goalId||""};
    savedTaskId=itemId||id("task");savedTaskDate=obj.date||null;
    const tasks=itemId?data.tasks.map(x=>x.id===itemId?{...x,...obj,id:itemId}:x):[...data.tasks,{id:savedTaskId,completed:false,createdAt:todayKey(),...obj}];
    let priorities=data.priorities;
    if(itemId && old?.priorityId && old.priorityId!==obj.priorityId){
      priorities=priorities.map(p=>p.id===old.priorityId?{...p,taskIds:(p.taskIds||[]).filter(id=>id!==itemId)}:p);
    }
    if(obj.priorityId)priorities=priorities.map(p=>p.id===obj.priorityId?{...p,taskIds:[...new Set([...(p.taskIds||[]),savedTaskId])]}:p);
    data={...data,tasks,priorities};
  }else if(t==="habit-new"||t==="habit-edit"){
    const ds=[...document.querySelectorAll("[data-habit-day]:checked")].map(x=>Number(x.dataset.habitDay)),obj={name:(f.name||"").trim()||"Hábito",target:f.target||"",frequency:f.frequency||"daily",daysOfWeek:ds.length?ds:DAY_NUMS,logs:itemId?(findItem(t,itemId)?.logs||{}):{}};
    data={...data,habits:itemId?data.habits.map(x=>x.id===itemId?{...x,...obj}:x):[...data.habits,{id:id("habit"),...obj}]};
  }else if(t==="priority-new"||t==="priority-edit"){
    const taskIds=[...document.querySelectorAll("[data-priority-task]:checked")].map(x=>x.dataset.priorityTask),old=findItem(t,itemId),list=prioritiesFor(currentDate());
    if(!itemId&&list.length>=3){state.modal=null;toast("Esta semana ya tiene 3 prioridades.");render();return}
    const priorityId=itemId||id("priority"),weekStart=old?.weekStart||currentWeekStart(),obj={id:priorityId,title:(f.title||"").trim()||"Prioridad",progress:Number(f.progress)||0,taskIds,weekStart};
    let tasks=data.tasks.map(task=>{
      if(taskIds.includes(task.id))return {...task,priorityId};
      if(itemId&&task.priorityId===itemId)return {...task,priorityId:""};
      return task;
    });
    let priorities=itemId?data.priorities.map(x=>x.id===itemId?obj:x):[...data.priorities,obj];
    priorities=priorities.map(p=>p.id===priorityId?p:{...p,taskIds:(p.taskIds||[]).filter(id=>!taskIds.includes(id)||p.id===priorityId)});
    data={...data,tasks,priorities};
  }else if(t==="training-new"||t==="training-edit"){
    const slot=Number(f.slot)||1,obj={title:(f.title||"").trim()||("Entrenamiento "+slot),slot,date:f.date||state.date,time:f.time||"19:00",durationMinutes:Number(f.durationMinutes)||60,type:f.type||"General",perception:f.perception||"",completed:!!f.completed,note:f.note||""};
    savedTrainingDate=obj.date;
    data={...data,training:itemId?data.training.map(x=>x.id===itemId?{...x,...obj}:x):[...data.training,{id:id("training"),...obj}]};
  }else if(t==="goal-new"||t==="goal-edit"){
    const priorityIds=[...document.querySelectorAll("[data-goal-priority]:checked")].map(x=>x.dataset.goalPriority),taskIds=[...document.querySelectorAll("[data-goal-task]:checked")].map(x=>x.dataset.goalTask),habitIds=[...document.querySelectorAll("[data-goal-habit]:checked")].map(x=>x.dataset.goalHabit),obj={title:(f.title||"").trim()||"Nueva meta",icon:f.icon||"🎯",category:f.category||"Personal",progress:Number(f.progress)||0,targetDate:f.targetDate||"",priorityIds,taskIds,habitIds};
    data={...data,goals:itemId?data.goals.map(x=>x.id===itemId?{...x,...obj}:x):[...data.goals,{id:id("goal"),...obj}]};
  }else if(t==="nonneg-new"||t==="nonneg-edit"){
    const ds=[...document.querySelectorAll("[data-nonneg-day]:checked")].map(x=>Number(x.dataset.nonnegDay)),old=findItem(t,itemId),obj={name:(f.name||"").trim()||"Nuevo acuerdo",icon:f.icon||"✓",target:f.target||"Diario",mode:f.mode||"manual",slot:f.mode==="training"?(Number(f.slot)||1):undefined,active:!!f.active,days:ds.length?ds:DAY_NUMS,checks:old?.checks||{}};
    data={...data,nonNegotiables:itemId?data.nonNegotiables.map(x=>x.id===itemId?{...x,...obj}:x):[...data.nonNegotiables,{id:id("nonneg"),...obj}]};
  }
  repairPriorityRelations();
  if(savedTaskDate){const w=ensureWeek(data,weekKey(savedTaskDate));w.plannedDays[savedTaskDate]=true;}
  if(savedTrainingDate){const w=ensureWeek(data,weekKey(savedTrainingDate));w.plannedDays[savedTrainingDate]=true;}
  data=save(data);
  state.modal=null;
  render();
  toast("Guardado");
}
document.addEventListener("click",e=>{
  const el=e.target.closest("[data-action]");if(!el)return;const a=el.dataset.action;
  if(a==="toggle"){state.open[el.dataset.id]=!state.open[el.dataset.id];render();return}
  if(a==="nav"){state.page=el.dataset.page;state.mobileMenu=false;if(state.page==="plan")state.view="planning";render();return}
  if(a==="mobile-menu"){state.mobileMenu=!state.mobileMenu;render();return}
  if(a==="view"){state.view=el.dataset.view;render();return}
  if(a==="today"){state.date=todayKey();state.month=key(new Date(new Date().getFullYear(),new Date().getMonth(),1));state.page="plan";state.view="planning";render();return}
  if(a==="date-nav"){const n=Number(el.dataset.delta);if(state.view==="day")state.date=key(add(currentDate(),n));else if(state.view==="week"||state.view==="planning")state.date=key(add(currentDate(),n*7));else{const d=parse(state.month);d.setMonth(d.getMonth()+n);state.month=key(new Date(d.getFullYear(),d.getMonth(),1))}render();return}
  if(a==="month-nav"){const d=parse(state.month);d.setMonth(d.getMonth()+Number(el.dataset.delta));state.month=key(new Date(d.getFullYear(),d.getMonth(),1));render();return}
  if(a==="go-date"){state.date=el.dataset.date;state.month=key(parse(state.date));state.page="plan";state.view="day";render();return}
  if(a==="mood"){setDay({mood:el.dataset.mood});return}
  if(a==="mood-date"){const k=el.dataset.date||state.date;setData(d=>{ensureDay(d,k).mood=el.dataset.mood;return d});return}
  if(a==="plan-day-toggle"){setPlannedDay(el.dataset.date,!dayHasPlan(el.dataset.date));return}
  if(a==="task-assign"){const t=data.tasks.find(x=>x.id===el.dataset.id);if(!t)return;const day=el.dataset.day,assigning=t.date!==day;setData(d=>({...d,tasks:d.tasks.map(x=>x.id===t.id?{...x,date:assigning?day:""}:x)}));if(assigning)setPlannedDay(day,true);return}
  if(a==="nonneg-toggle-date"){const n=data.nonNegotiables.find(x=>x.id===el.dataset.id);if(n)toggleNonnegForDate(n,el.dataset.date);return}
  if(a==="nav-goals"){state.page="goals";state.mobileMenu=false;render();return}
  if(a==="task-toggle"){setData(d=>({...d,tasks:d.tasks.map(t=>t.id===el.dataset.id?{...t,completed:!t.completed}:t)}));return}
  if(a==="task-delete"){setData(d=>({...d,tasks:d.tasks.filter(t=>t.id!==el.dataset.id)}));return}
  if(a==="task-tomorrow"){const t=data.tasks.find(x=>x.id===el.dataset.id);if(t)setData(d=>({...d,tasks:d.tasks.map(x=>x.id===t.id?{...x,date:key(add(t.date?parse(t.date):currentDate(),1))}:x)}));return}
  if(a==="habit-toggle"){setData(d=>({...d,habits:d.habits.map(h=>h.id===el.dataset.id?{...h,logs:{...(h.logs||{}),[el.dataset.date]:!h.logs?.[el.dataset.date]}}:h)}));return}
  if(a==="habit-delete"){setData(d=>({...d,habits:d.habits.filter(h=>h.id!==el.dataset.id)}));return}
  if(a==="training-toggle"){setData(d=>({...d,training:d.training.map(t=>t.id===el.dataset.id?{...t,completed:!t.completed}:t)}));return}
  if(a==="minimal-toggle"){const r=dayRecord();setDay({minimalPlan:{...r.minimalPlan,[el.dataset.key]:!r.minimalPlan?.[el.dataset.key]}});return}
  if(a==="nonneg-toggle"){const n=data.nonNegotiables.find(x=>x.id===el.dataset.id);if(n)toggleNonnegForDate(n,state.date);return}
  if(a==="goal-delete"){setData(d=>({...d,goals:d.goals.filter(g=>g.id!==el.dataset.id)}));return}
  if(a==="modal"){state.modal={type:el.dataset.type,id:el.dataset.id||undefined,noDate:el.dataset.noDate==="true",plannedDate:el.dataset.plannedDate||undefined};render();return}
  if(a==="close-modal"){if(el.hasAttribute("data-modal-inner"))return;state.modal=null;render();return}
  if(a==="modal-save"){saveModal();return}
  if(a==="reset"){reset();return}
  if(a==="notification-enable"||a==="notification-settings"){openNotificationSettings();return}
  if(a==="notification-test"){testNotification();return}
  if(a==="install-pwa"){installPwa();return}
  if(a==="sync-now"){syncRemote();return}
  if(a==="export"){exportBackup();return}
});
document.addEventListener("change",e=>{
  const el=e.target;
  if(el.matches("[data-field]")){setDay({[el.dataset.field]:el.type==="number"?Number(el.value):Number(el.value)});return}
  if(el.matches("[data-reflection]")){setReflection(el.dataset.reflection,el.value);return}
  if(el.matches("[data-weekly]")){setWeeklyField(el.dataset.weekly,el.value);return}
  if(el.matches("[data-setting]")){setData(d=>({...d,settings:{...d.settings,[el.dataset.setting]:Math.max(0,Number(el.value))}}));return}
  if(el.matches("[data-setting-notification]")){setData(d=>({...d,notifications:{...d.notifications,[el.dataset.settingNotification]:el.type==="checkbox"?el.checked:Number(el.value)}}));return}
  if(el.matches("[data-sync-setting]")){setData(d=>({...d,sync:{...d.sync,[el.dataset.syncSetting]:el.type==="checkbox"?el.checked:el.value}}));return}
  if(el.matches('input[type="file"][data-action="import"]'))importBackup(el.files?.[0]);
});
function bindGlobal(){document.querySelectorAll("[data-range-output]").forEach(i=>i.addEventListener("input",()=>{const o=document.getElementById(i.dataset.rangeOutput);if(o)o.textContent=i.value+"%"}))}
async function openNotificationSettings(){if(!("Notification"in window)){toast("Este navegador no admite notificaciones.");return}if(location.protocol!=="https:"&&location.hostname!=="localhost"&&location.hostname!=="127.0.0.1"){toast("Las notificaciones requieren HTTPS o localhost.");return}const perm=Notification.permission==="granted"?"granted":await Notification.requestPermission();if(perm!=="granted"){toast("Permiso de notificaciones: "+perm);return}data=save({...data,notifications:{...data.notifications,enabled:true}});render();toast("Notificaciones activadas.");await maybeSubscribePush()}
async function maybeSubscribePush(){if(!CONFIG.vapidPublicKey||!("serviceWorker"in navigator)||!("PushManager"in window))return;try{const reg=await navigator.serviceWorker.ready,sub=await reg.pushManager.getSubscription();if(sub)return;const s=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:base64ToBytes(CONFIG.vapidPublicKey)});localStorage.setItem("plan20-push-subscription",JSON.stringify(s.toJSON()))}catch(e){console.warn("PLAN20 push",e)}}
function base64ToBytes(b){const pad="=".repeat((4-b.length%4)%4),raw=atob((b+pad).replace(/-/g,"+").replace(/_/g,"/")),a=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)a[i]=raw.charCodeAt(i);return a}
async function testNotification(){if(!("Notification"in window)){toast("Notificaciones no disponibles.");return}if(Notification.permission!=="granted"){await openNotificationSettings();return}try{const reg=await navigator.serviceWorker.ready;await reg.showNotification("PLAN 2.0",{body:"La notificación de prueba funciona.",icon:"./public/icons/icon-192.svg",badge:"./public/icons/icon-192.svg",tag:"plan20-test",data:{url:"./"}})}catch{try{new Notification("PLAN 2.0",{body:"La notificación de prueba funciona."})}catch{toast("No se pudo mostrar la notificación.")}}}
function loadNotify(k){return !!notifyLog[k]}
function markNotify(k){notifyLog[k]=Date.now();try{localStorage.setItem(NOTIFY_LOG_KEY,JSON.stringify(notifyLog))}catch{}}
function scheduleLocalReminderCheck(){if(reminderTimer)return;reminderTimer=setInterval(checkLocalReminders,30000);setTimeout(checkLocalReminders,1200)}
async function checkLocalReminders(){if(!data.notifications.enabled||!("Notification"in window)||Notification.permission!=="granted")return;const k=todayKey(),now=new Date(),nowM=now.getHours()*60+now.getMinutes(),lead=Number(data.notifications.leadMinutes)||0;for(const t of tasksFor(k).filter(x=>!x.completed&&x.time)){const tm=minutesFromTime(t.time);if(tm===null)continue;if(tm>=nowM&&tm-nowM<=lead)await maybeNotify(`due-${k}-${t.id}`,"⏰ "+t.title,"Empieza ahora · "+t.time,t.id);if(data.notifications.overdue&&tm<nowM)await maybeNotify(`overdue-${k}-${t.id}`,"⚠️ Pendiente: "+t.title,"Estaba planificada para las "+t.time,t.id)}}
async function maybeNotify(k,title,body,taskId){if(loadNotify(k))return;try{const reg=await navigator.serviceWorker.ready;await reg.showNotification(title,{body,icon:"./public/icons/icon-192.svg",badge:"./public/icons/icon-192.svg",tag:k,renotify:false,data:{url:"./?date="+todayKey()+(taskId?"&task="+encodeURIComponent(taskId):"")}});markNotify(k)}catch{}}
async function installPwa(){if(state.deferredInstallPrompt){state.deferredInstallPrompt.prompt();try{await state.deferredInstallPrompt.userChoice}catch{}state.deferredInstallPrompt=null;render();return}toast("Usa el menú del navegador: “Instalar app” o “Añadir a pantalla de inicio”.")}
window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();state.deferredInstallPrompt=e;render()});
window.addEventListener("appinstalled",()=>{state.deferredInstallPrompt=null;render();toast("PLAN 2.0 instalado.")});
window.addEventListener("online",()=>{if(data.sync.enabled)syncRemote()});
installSyncListeners(incoming=>{if(incoming.meta?.updatedAt===data.meta?.updatedAt)return;data=incoming;repairPriorityRelations();render()});
async function syncRemote(){if(!data.sync.enabled||!data.sync.endpoint){toast("Configura un endpoint de sincronización.");return}try{const headers={"Content-Type":"application/json"};if(data.sync.token)headers.Authorization="Bearer "+data.sync.token;const r=await fetch(data.sync.endpoint,{headers,cache:"no-store"});let remote=null;if(r.ok){const p=await r.json();remote=p.data||p}const lt=Date.parse(data.meta?.updatedAt||0)||0,rt=Date.parse(remote?.meta?.updatedAt||remote?.updatedAt||0)||0;if(remote&&rt>lt){data=replace(remote);render();toast("Descargamos una versión más nueva.")}else{const u=await fetch(data.sync.endpoint,{method:"PUT",headers,body:JSON.stringify({data,updatedAt:data.meta.updatedAt})});if(!u.ok)throw new Error("HTTP "+u.status);data=save({...data,sync:{...data.sync,lastSync:new Date().toISOString()}},false);render();toast("Sincronización completada.")}}catch(e){console.warn("PLAN20 sync",e);toast("No se pudo sincronizar: revisa el endpoint.")}}
function exportBackup(){const blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"}),u=URL.createObjectURL(blob),a=document.createElement("a");a.href=u;a.download="plan20-respaldo-"+todayKey()+".json";a.click();URL.revokeObjectURL(u);toast("Respaldo exportado.")}
async function importBackup(file){if(!file)return;try{const x=JSON.parse(await file.text());if(!x||typeof x!=="object"||!Array.isArray(x.tasks))throw new Error("Formato");data=replace(x);render();toast("Respaldo importado.")}catch{toast("No se pudo importar ese respaldo.")}}
registerServiceWorker().then(()=>{});
render();
scheduleLocalReminderCheck();